CREATE TABLE atlys_dataset.link_opened (`id` FixedString(32) COMMENT 'event id, unique per row' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `share_id` FixedString(32) COMMENT 'share instance id, funnel join key' CODEC(ZSTD(1)), `channel` LowCardinality(String) COMMENT 'channel the link was opened from, 4 values', `recipient_is_new_user` UInt8 COMMENT '1 if recipient is new to Atlys, else 0' CODEC(T64, ZSTD(1)), `destination` LowCardinality(String) COMMENT 'destination country ISO-2, 14 values') ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (recipient_is_new_user, channel, destination, share_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'link_opened: recipient opens shared link; funnel step 4, one share_id can have many opens (Visa Status Sharing spec)'
CREATE TABLE atlys_dataset.link_generated (`id` FixedString(32) COMMENT 'event id, unique per row' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/web-user-b2c/Desktop/android, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT '5.1% empty, bucket as \'unknown\'', `app_version` LowCardinality(String) COMMENT 'client app version, 3 values', `geoip_country_code` LowCardinality(String) COMMENT 'sharer geo country, 7 values', `city` LowCardinality(String) COMMENT 'sharer geo city, 7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js, 2 values', `user_id` String COMMENT 'sharer user id, 28 chars, high cardinality' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'sharer\'s visa application id' CODEC(ZSTD(1)), `share_id` FixedString(32) COMMENT 'share instance id, funnel join key' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'destination country ISO-2, 14 values', `status_shared` LowCardinality(String) COMMENT 'app status at share time: submitted/processing/approved', `channel` LowCardinality(String) COMMENT 'channel the link was generated for, 4 values') ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (channel, status_shared, share_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'link_generated: share link created for share_id; funnel step 3, feeds link_opened (Visa Status Sharing spec)'
CREATE TABLE atlys_dataset.recipient_cta_clicked (`id` FixedString(32) COMMENT 'event id, unique per row' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `share_id` FixedString(32) COMMENT 'share instance id, funnel join key' CODEC(ZSTD(1)), `cta` LowCardinality(String) COMMENT 'CTA tapped, currently 1 value, may grow', `destination` LowCardinality(String) COMMENT 'destination country ISO-2, 14 values') ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (destination, share_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'recipient_cta_clicked: recipient taps start-own-application; funnel step 5 / K-factor conversion (Visa Status Sharing spec)'
CREATE TABLE atlys_dataset.channel_selected (`id` FixedString(32) COMMENT 'event id, unique per row' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/web-user-b2c/Desktop/android, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT '5.1% empty, bucket as \'unknown\'', `app_version` LowCardinality(String) COMMENT 'client app version, 3 values', `geoip_country_code` LowCardinality(String) COMMENT 'sharer geo country, 7 values', `city` LowCardinality(String) COMMENT 'sharer geo city, 7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js, 2 values', `user_id` String COMMENT 'sharer user id, 28 chars, high cardinality' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'sharer\'s visa application id' CODEC(ZSTD(1)), `share_id` FixedString(32) COMMENT 'share instance id, funnel join key' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'destination country ISO-2, 14 values', `status_shared` LowCardinality(String) COMMENT 'app status at share time: submitted/processing/approved', `channel` LowCardinality(String) COMMENT 'chosen channel: whatsapp/email/copy_link/sms, 4 values') ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (channel, status_shared, share_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'channel_selected: sharer picks a channel; funnel step 2, joins via share_id (Visa Status Sharing spec)'
CREATE TABLE atlys_dataset.share_clicked (`id` FixedString(32) COMMENT 'event id, unique per row' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/web-user-b2c/Desktop/android, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT '5.6% empty, bucket as \'unknown\'', `app_version` LowCardinality(String) COMMENT 'client app version, 3 values', `geoip_country_code` LowCardinality(String) COMMENT 'sharer geo country, 7 values', `city` LowCardinality(String) COMMENT 'sharer geo city, 7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js, 2 values', `user_id` String COMMENT 'sharer user id, 28 chars, high cardinality' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'sharer\'s visa application id' CODEC(ZSTD(1)), `share_id` FixedString(32) COMMENT 'share instance id, funnel join key' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'destination country ISO-2, 14 values', `status_shared` LowCardinality(String) COMMENT 'app status at share time: submitted/processing/approved') ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (status_shared, destination, share_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'share_clicked: sharer taps share; funnel step 1, joins downstream via share_id (Visa Status Sharing spec)'